// Many games stepped together for training, with observations encoded inside the simulator. `Batch`
// sends each observation out as the ladder's JSON; at training speed that costs far more than the
// game (a tick resolves in a few microseconds), so this batch writes every seat's `Basic` encoding,
// action mask, reward and done flag straight into one ArrayBuffer, and reads actions from it. The
// Python package views the buffer in place, with no copies and no JSON. The match is still
// MatchCore, observed and resolved as on the ladder; only the per-tick state hash is left out of
// replays, since hashing costs more than the tick.

import { encodeReplay, rngInt, rngSeed, type Observation, type RngState } from "@arena/engine";
import type { HelloMsg } from "@arena/protocol";
import { setUpMatch, type HouseSeat } from "./game.ts";
import { frameOutcome, type MatchCore, type TurnOutcome } from "./match.ts";
import {
  frameOf,
  gridLength,
  resolveBot,
  resolveEncoder,
  trusted,
  type EncoderOutput,
  type SeatEncoder,
  type SimBot,
  type SimEncoder,
  type TurnReply,
} from "./plugins.ts";
import { wire } from "./wire.ts";
import { VectorProfiler, type VectorProfile } from "./profiling.ts";

/**
 * An opponent or teacher played by the caller: the batch hands out its seats' observations as JSON
 * (`pending`) and takes back its turns (`answer`). This is how the Python package runs bots written
 * in Python inside the fast environments.
 */
export const EXTERNAL = "@external";

export interface VectorOptions {
  /** opt-in phase timings: sample every 16 steps, or choose a positive interval; off by default */
  profile?: boolean | { every: number };
  /** fighter 2 of each game: a bot (a house bot's name, a registered bot's, a `SimBot`, or EXTERNAL), or null to play it yourself; spread over the games in turn (default: all yours) */
  opponents?: (string | SimBot | null)[];
  /** the encoder: "basic" (default), a registered encoder's name, or a `SimEncoder` */
  encoder?: string | SimEncoder;
  /** a bot whose turn on each of your seats, as the encoder's closest action, is written to `teacher` (-1 for none); null for none */
  teacher?: string | SimBot | null;
  /** the fighters the teacher labels, where you play them (default: both) */
  taught?: number[];
  /** a shipped map's name; by default each game's seed picks one, as the ladder does */
  map?: string;
  /** the shaped reward, or win (1), loss (-1) and draw (0) at the end only (default) */
  reward?: "win_loss" | "damage_trade";
  /** restart a finished game on the step after it ends (default), or on the same step, keeping its last observation in `final_grid` and `final_vec` */
  autoreset?: "next_step" | "same_step";
  /** `basic`'s grid size (default 21) */
  size?: number;
  /** `basic`'s grid as float32 values (default), or a byte per tile, a quarter the size, that `decodeBasicGrid` turns back into them exactly */
  grid?: "float32" | "uint8";
}

/** Where each array lives in `buffer`: a byte offset and a length in elements. */
export type VectorLayout = Record<
  | "grid"
  | "vec"
  | "final_grid"
  | "final_vec"
  | "reward"
  | "dealt"
  | "taken"
  | "action"
  | "seed"
  | "teacher"
  | "mask"
  | "terminated"
  | "result",
  { offset: number; length: number }
>;

/** The shape of one seat's arrays: the encoder's. */
export interface VectorSpec {
  gridShape: number[];
  gridType: "float32" | "uint8";
  features: number;
  actions: number;
}

interface Player {
  id: number;
  encoder: SeatEncoder;
  /** this seat's observation now */
  obs: Observation;
  /** the teacher's decisions for this seat, when a bot in the batch teaches */
  teacher: ((obs: Observation) => TurnReply | null) | null;
}

interface Slot {
  core: MatchCore;
  /** a bot playing fighter 2 inside the batch */
  house: HouseSeat | null;
  /** fighter 2 played by the caller: its hello until `pending` hands it out, and its reply for this tick */
  external: { hello: HelloMsg | null; obs: Observation; reply: TurnReply | null } | null;
  seed: number;
  players: Player[];
  /** the hellos of your fighters, until `pending` hands them to an external teacher */
  hellos: Map<number, HelloMsg> | null;
  over: boolean;
}

/**
 * `numGames` games, each with two seats in the buffer: seat 2g is game g's fighter 1 and seat 2g+1
 * its fighter 2. A fighter 2 played by a bot runs inside the game and its seat is left alone.
 * Write each seat's action, call `step`, and read what comes back.
 */
export class VectorBatch {
  readonly numGames: number;
  readonly numSeats: number;
  readonly buffer: ArrayBuffer;
  readonly layout: VectorLayout;
  readonly spec: VectorSpec;
  private opts: Required<
    Omit<VectorOptions, "map" | "opponents" | "encoder" | "teacher" | "profile">
  > & {
    map?: string;
  };
  private opponents: (string | SimBot | null)[] = [];
  private teacherBot: SimBot | typeof EXTERNAL | null = null;
  private encoder: SimEncoder;
  private profiler: VectorProfiler | null;
  /** turns from this encoder skip the protocol's schema check, and it fills every value itself */
  private trusted: boolean;
  private gridLength: number;
  /** each seat's place in the arrays, made once */
  private outs: EncoderOutput[];
  private grid: Float32Array | Uint8Array;
  private vec: Float32Array;
  private finalGrid: Float32Array | Uint8Array;
  private finalVec: Float32Array;
  private reward: Float32Array;
  private dealt: Float32Array;
  private taken: Float32Array;
  private action: Int32Array;
  private seed: Int32Array;
  private teacher: Int32Array;
  private mask: Int8Array;
  private terminated: Uint8Array;
  private result: Int8Array;
  private slots: Slot[] = [];
  /** each slot's most recently finished match, for its replay */
  private finished: (MatchCore | null)[];
  private rng: RngState = rngSeed(0);

  constructor(numGames: number, opts: VectorOptions = {}) {
    if (!Number.isInteger(numGames) || numGames < 1)
      throw new Error("a batch needs at least one game");
    this.profiler = opts.profile
      ? new VectorProfiler(typeof opts.profile === "object" ? opts.profile.every : 16)
      : null;
    this.numGames = numGames;
    this.numSeats = 2 * numGames;
    this.opts = {
      reward: opts.reward ?? "win_loss",
      autoreset: opts.autoreset ?? "next_step",
      size: opts.size ?? 21,
      grid: opts.grid ?? "float32",
      taught: opts.taught ?? [1, 2],
      ...(opts.map ? { map: opts.map } : {}),
    };
    if (!["win_loss", "damage_trade"].includes(this.opts.reward))
      throw new Error(`unknown reward '${this.opts.reward}' (win_loss, damage_trade)`);
    if (!["next_step", "same_step"].includes(this.opts.autoreset))
      throw new Error(`unknown autoreset '${this.opts.autoreset}' (next_step, same_step)`);
    if (!["float32", "uint8"].includes(this.opts.grid))
      throw new Error(`unknown grid '${this.opts.grid}' (float32, uint8)`);
    this.encoder = resolveEncoder(opts.encoder, this.opts);
    this.trusted = trusted(this.encoder);
    this.setOpponents(opts.opponents ?? [null]);
    this.setTeacher(opts.teacher ?? null);
    const e = this.encoder;
    this.spec = {
      gridShape: [...e.gridShape],
      gridType: e.gridType ?? "float32",
      features: e.features,
      actions: e.actions,
    };
    const coded = this.spec.gridType === "uint8";
    this.gridLength = gridLength(e);
    const seats = this.numSeats;
    const lengths: Record<keyof VectorLayout, number> = {
      grid: seats * this.gridLength,
      vec: seats * e.features,
      final_grid: seats * this.gridLength,
      final_vec: seats * e.features,
      reward: seats,
      dealt: seats,
      taken: seats,
      action: seats,
      seed: seats,
      teacher: seats,
      mask: seats * e.actions,
      terminated: seats,
      result: seats,
    };
    const gridBytes = coded ? 1 : 4;
    const sections: [keyof VectorLayout, number][] = [
      ["grid", gridBytes],
      ["vec", 4],
      ["final_grid", gridBytes],
      ["final_vec", 4],
      ["reward", 4],
      ["dealt", 4],
      ["taken", 4],
      ["action", 4],
      ["seed", 4],
      ["teacher", 4],
      ["mask", 1],
      ["terminated", 1],
      ["result", 1],
    ];
    sections.sort((a, b) => b[1] - a[1]); // 4-byte elements first, so every typed array is aligned
    let offset = 0;
    const layout = {} as VectorLayout;
    for (const [name, bytes] of sections) {
      layout[name] = { offset, length: lengths[name] };
      offset += lengths[name] * bytes;
    }
    this.layout = layout;
    this.buffer = new ArrayBuffer(offset);
    const at = (name: keyof VectorLayout) =>
      [this.buffer, layout[name].offset, layout[name].length] as const;
    this.grid = coded ? new Uint8Array(...at("grid")) : new Float32Array(...at("grid"));
    this.vec = new Float32Array(...at("vec"));
    this.finalGrid = coded
      ? new Uint8Array(...at("final_grid"))
      : new Float32Array(...at("final_grid"));
    this.finalVec = new Float32Array(...at("final_vec"));
    this.reward = new Float32Array(...at("reward"));
    this.dealt = new Float32Array(...at("dealt"));
    this.taken = new Float32Array(...at("taken"));
    this.action = new Int32Array(...at("action"));
    this.seed = new Int32Array(...at("seed"));
    this.teacher = new Int32Array(...at("teacher"));
    this.mask = new Int8Array(...at("mask"));
    this.terminated = new Uint8Array(...at("terminated"));
    this.result = new Int8Array(...at("result"));
    this.outs = Array.from({ length: seats }, (_, s) => ({
      grid: this.grid.subarray(s * this.gridLength, (s + 1) * this.gridLength),
      vec: this.vec.subarray(s * e.features, (s + 1) * e.features),
      mask: this.mask.subarray(s * e.actions, (s + 1) * e.actions),
    }));
    this.teacher.fill(-1);
    this.finished = Array.from({ length: numGames }, () => null);
  }

  /** Fighter 2 for the games that start from now on: a bot, EXTERNAL or null (yours), spread over the games in turn. */
  setOpponents(opponents: (string | SimBot | null)[]): void {
    if (!Array.isArray(opponents) || opponents.length === 0)
      throw new Error("opponents is a non-empty list of bots or null");
    for (const o of opponents) if (o !== null && o !== EXTERNAL) resolveBot(o);
    this.opponents = Array.from(
      { length: this.numGames },
      (_, g) => opponents[g % opponents.length]!,
    );
  }

  /** The teacher for the games that start from now on: a bot, EXTERNAL, or null for none. */
  setTeacher(teacher: string | SimBot | null): void {
    this.teacherBot =
      teacher === null ? null : teacher === EXTERNAL ? EXTERNAL : resolveBot(teacher).bot;
  }

  /** Which games' fighter 2 is played inside the batch or by the caller (1) or by you from the buffer (0), by game. */
  houseGames(): number[] {
    return this.slots.map((s) => (s.house || s.external ? 1 : 0));
  }

  /** Starts every game over, drawing their seeds from `seed`. */
  reset(seed: number): void {
    this.rng = rngSeed(seed);
    this.slots = [];
    this.reward.fill(0);
    this.dealt.fill(0);
    this.taken.fill(0);
    this.terminated.fill(0);
    this.result.fill(0);
    for (let g = 0; g < this.numGames; g++) this.slots.push(this.start(g));
  }

  /**
   * Plays one tick of every game from the actions in the buffer. A game that ended on the last step
   * starts over instead (with next-step autoreset), ignoring its actions. Afterwards the buffer holds
   * each seat's observation, mask, reward, damage dealt and taken, whether its game just ended and,
   * if so, its result.
   */
  step(): void {
    if (this.slots.length === 0) throw new Error("reset the batch before stepping it");
    const profile = this.profiler?.begin();
    this.reward.fill(0);
    this.dealt.fill(0);
    this.taken.fill(0);
    this.terminated.fill(0);
    this.result.fill(0);
    profile?.mark("other");
    for (let g = 0; g < this.numGames; g++) {
      if (this.slots[g]!.over) {
        this.slots[g] = this.start(g);
        profile?.reset();
        profile?.mark("reset");
        continue;
      }
      profile?.game();
      const slot = this.slots[g]!;
      const tick = slot.core.state.tick;
      const outcomes: Record<number, TurnOutcome> = {};
      for (const p of slot.players) {
        const turn = p.encoder.turn(this.action[this.seatOf(g, p.id)]!);
        outcomes[p.id] = this.trusted
          ? { turn, failed: false }
          : frameOutcome(frameOf(turn, tick), tick);
      }
      const h = slot.house;
      if (h) outcomes[h.fighterId] = frameOutcome(h.reply(h.obs!), tick);
      const x = slot.external;
      if (x) outcomes[2] = frameOutcome(frameOf(x.reply, tick), tick);
      profile?.mark("actions");
      const result = slot.core.resolve(outcomes);
      profile?.mark("simulation");
      if (result) {
        slot.over = true;
        this.finished[g] = slot.core;
        for (const p of slot.players) {
          const seat = this.seatOf(g, p.id);
          const outcome = result.winner === null ? 0 : result.winner === p.id ? 1 : -1;
          this.terminated[seat] = 1;
          this.result[seat] = outcome;
          this.reward[seat] = outcome;
        }
        profile?.mark("other");
        if (this.opts.autoreset === "same_step") {
          // The last observations acted on, then the next match starts at once.
          for (const p of slot.players) this.keepFinal(this.seatOf(g, p.id));
          this.slots[g] = this.start(g);
          profile?.reset();
          profile?.mark("reset");
        }
        continue;
      }
      for (const p of slot.players) {
        const obs = slot.core.takeObservation(p.id);
        profile?.mark("observation");
        const seat = this.seatOf(g, p.id);
        const me = p.obs.self;
        let dealt = 0;
        for (const e of obs.events)
          if ((e.kind === "hit" || e.kind === "wall_slam") && e.attacker === me.id)
            dealt += e.damage;
        const taken = Math.max(0, me.hp - obs.self.hp); // a heal isn't damage taken
        this.dealt[seat] = dealt / me.max_hp;
        this.taken[seat] = taken / me.max_hp;
        if (this.opts.reward === "damage_trade") this.reward[seat] = (dealt - taken) / me.max_hp;
        p.obs = obs;
        profile?.mark("other");
        this.observe(g, p, profile);
      }
      if (h) {
        const obs = slot.core.takeObservation(h.fighterId);
        profile?.mark("observation");
        h.obs = wire(obs);
        profile?.mark("wire");
      }
      if (x) {
        x.obs = slot.core.takeObservation(2);
        profile?.mark("observation");
        x.reply = null;
      }
      profile?.mark("other");
    }
    this.profiler?.end();
  }

  /** Detached aggregate timings; optionally clear counters without resetting games. Null when disabled. */
  profile(reset = false): VectorProfile | null {
    return this.profiler?.snapshot(reset) ?? null;
  }

  /**
   * The seats the caller plays or teaches this tick, as JSON: a list of `[game, fighter, role,
   * hello, observation]`, where role is "opponent" (an EXTERNAL fighter 2: answer with its turn) or
   * "teacher" (one of your seats, with an EXTERNAL teacher: answer with the teacher's turn there),
   * and hello is the match's hello the first time a seat is listed, else null.
   */
  pending(): string {
    const out: string[] = [];
    const entry = (
      g: number,
      id: number,
      role: string,
      hello: HelloMsg | null | undefined,
      obs: Observation,
    ) =>
      out.push(
        `[${g},${id},"${role}",${hello ? JSON.stringify(hello) : "null"},${JSON.stringify(obs)}]`,
      );
    this.slots.forEach((slot, g) => {
      if (slot.over) return;
      if (this.teacherBot === EXTERNAL) {
        for (const p of slot.players)
          if (this.opts.taught.includes(p.id))
            entry(g, p.id, "teacher", slot.hellos?.get(p.id), p.obs);
        slot.hellos = null;
      }
      const x = slot.external;
      if (x) {
        entry(g, 2, "opponent", x.hello, x.obs);
        x.hello = null;
      }
    });
    return `[${out.join(",")}]`;
  }

  /** The caller's turns for what `pending` listed, in its order, as JSON (null for no turn). */
  answer(turns: string): void {
    const all = JSON.parse(turns) as [number, number, string, TurnReply | null][];
    for (const [g, id, role, turn] of all) {
      const slot = this.slots[g];
      if (!slot || slot.over) continue;
      if (role === "opponent" && slot.external) slot.external.reply = turn;
      if (role === "teacher") {
        const p = slot.players.find((q) => q.id === id);
        if (p) this.teacher[this.seatOf(g, id)] = turn ? this.label(g, p, turn) : -1;
      }
    }
  }

  /** Slot `g`'s most recently finished match as a replay file's text (JSON Lines), or null if none has finished. */
  replayText(g: number): string | null {
    const core = this.finished[g];
    return core ? encodeReplay(core.summary().replay) : null;
  }

  private seatOf(game: number, fighterId: number): number {
    return 2 * game + fighterId - 1;
  }

  private start(g: number): Slot {
    const seed = rngInt(this.rng, 2 ** 31);
    const opponent = this.opponents[g] ?? null;
    const external = opponent === EXTERNAL;
    const m = setUpMatch(
      {
        seed,
        ...(this.opts.map ? { map: this.opts.map } : {}),
        ...(opponent && !external ? { opponent } : {}),
      },
      false,
    );
    const players = external ? [1] : m.players;
    const slot: Slot = {
      core: m.core,
      house: m.house,
      external: null,
      seed,
      players: [],
      hellos: this.teacherBot === EXTERNAL ? m.hellos : null,
      over: false,
    };
    const t = this.teacherBot;
    for (const id of players) {
      const hello = m.hellos.get(id)!;
      const taught = t && t !== EXTERNAL && this.opts.taught.includes(id);
      const p: Player = {
        id,
        encoder: this.encoder.start(hello),
        obs: m.core.takeObservation(id),
        teacher: taught ? t.start(hello) : null,
      };
      slot.players.push(p);
      this.observe(g, p);
    }
    if (slot.house) slot.house.obs = wire(m.core.takeObservation(slot.house.fighterId));
    if (external)
      slot.external = { hello: m.hellos.get(2)!, obs: m.core.takeObservation(2), reply: null };
    this.seed[2 * g] = this.seed[2 * g + 1] = seed;
    return slot;
  }

  /** Encodes a seat's observation, and labels it with the teacher's action. */
  private observe(g: number, p: Player, profile?: VectorProfiler | null): void {
    const seat = this.seatOf(g, p.id);
    const out = this.outs[seat]!;
    if (!this.trusted) {
      out.grid.fill(0);
      out.vec.fill(0);
      out.mask.fill(0);
    }
    p.encoder.encode(p.obs, out);
    profile?.encoded();
    profile?.mark("encoding");
    this.teacher[seat] = -1;
    if (p.teacher) {
      const turn = p.teacher(wire(p.obs));
      if (turn) this.teacher[seat] = this.label(g, p, turn);
      profile?.mark("teacher");
    }
  }

  /** The encoder's action for a turn on this seat, if the mask allows it, else -1. */
  private label(g: number, p: Player, turn: TurnReply): number {
    if (!p.encoder.action)
      throw new Error(
        "a teacher needs an encoder whose seats have action(turn), to turn its turns into actions",
      );
    const a = p.encoder.action(turn);
    return a >= 0 && a < this.spec.actions && this.outs[this.seatOf(g, p.id)]!.mask[a] ? a : -1;
  }

  private keepFinal(seat: number): void {
    const gs = this.gridLength;
    const fs = this.spec.features;
    this.finalGrid.set(this.grid.subarray(seat * gs, (seat + 1) * gs), seat * gs);
    this.finalVec.set(this.vec.subarray(seat * fs, (seat + 1) * fs), seat * fs);
  }
}
