// The rules, maps, starter and Random the ladder ships, built into the simulator so it works offline.
// A test checks the map list against maps/, so a new map can't be left out.

import { loadMap, loadRules, type GameMap, type Rules } from "@arena/engine";
import rulesJson from "../../../rules/rules.json" with { type: "json" };
import arena21 from "../../../maps/arena-21.json" with { type: "json" };
import columns21 from "../../../maps/columns-21.json" with { type: "json" };
import pillars21 from "../../../maps/pillars-21.json" with { type: "json" };
import { decide, type Match } from "../../../bots/ts-starter/strategy.ts";
import { random } from "../../../bots/random/policy.ts";
import { newCtx } from "../../../bots/lib/client.ts";
import type { SimBot } from "./plugins.ts";

export const SHIPPED_RULES: Rules = loadRules(rulesJson);

/** By name, in the ladder's order (it picks `maps[seed % maps.length]`). */
export const SHIPPED_MAPS: GameMap[] = [arena21, columns21, pillars21]
  .map((m) => loadMap(m))
  .sort((a, b) => (a.name < b.name ? -1 : 1));

/** Public practice opponents: the starter and the deliberately weak Random baseline. */
export const HOUSE_BOTS = {
  random: {
    name: "random",
    version: random.version,
    start(hello) {
      const ctx = newCtx(hello);
      return (obs) => random.decide(obs as never, ctx) as Record<string, unknown>;
    },
  },
  "ts-starter": {
    name: "ts-starter",
    version: "starter-17",
    start(hello) {
      const match: Match = { id: hello.match_id, rules: hello.rules as unknown as Match["rules"] };
      return (obs) => {
        try {
          return decide(obs as never, match) as Record<string, unknown>;
        } catch {
          return {};
        }
      };
    },
  },
} satisfies Record<string, SimBot>;
export type HouseBot = keyof typeof HOUSE_BOTS;
