// Your own code inside the simulator: bots to spar with or learn from, and encoders that turn
// observations into a network's arrays. The fast batch runs both in-process, so a bot of yours is
// an opponent as cheap as a house bot, and your encoding is written straight into the arrays your
// trainer reads, with no JSON in between. From another language (the Python package's embedded
// V8), a script registers them by name: `ArenaSim.registerBot(...)`, `ArenaSim.registerEncoder(...)`.

import type { Observation, Rules } from "@arena/engine";
import type { HelloMsg } from "@arena/protocol";
import {
  BASIC_ACTIONS,
  BASIC_ATTACKS,
  BASIC_CHANNELS,
  BASIC_FEATURES,
  BasicEncoder,
  basicTurn,
} from "./basic.ts";
import { HOUSE_BOTS } from "./shipped.ts";

/** A turn as a bot sends it: `move` or `dash`, `attack`, `shout` (its `tick` is filled in when missing). */
export type TurnReply = Record<string, unknown>;

/**
 * A bot that plays inside the simulator. For each match, `start` gets the bot's `hello` and returns
 * its decisions: a function from each observation (the JSON the ladder would send it) to the turn
 * it would reply with, or null for no reply. Keep per-match state in the closure. Its turns take
 * the ladder's path (the protocol's schema, then the match rules), so a malformed one is an idle,
 * failed tick as on the ladder. An exception stops the step it was thrown in, with its message.
 */
export interface SimBot {
  /** what replays record for it (default: its registered name, or "bot") */
  name?: string;
  version?: string;
  start(hello: HelloMsg): (observation: Observation) => TurnReply | null;
}

/** One seat's place in the batch's arrays, for an encoder to fill. */
export interface EncoderOutput {
  /** `gridShape` values, in row-major order */
  grid: Float32Array | Uint8Array;
  /** `features` numbers */
  vec: Float32Array;
  /** `actions` flags: 1 for an action your policy may choose now, 0 for one it may not */
  mask: Int8Array;
}

/**
 * Turns observations into a network's input and its actions back into turns. `start` is called for
 * each fighter in each match and returns that seat's encoder, which may remember what it has seen
 * (an enemy's last sighting, cooldowns it has worked out). Every array starts each tick at zero.
 */
export interface SimEncoder {
  /** the grid's shape for one seat, e.g. [channels, height, width]; [0] for no grid */
  gridShape: number[];
  /** the grid's values as floats (default), or bytes (a quarter of the memory to copy and keep) */
  gridType?: "float32" | "uint8";
  /** how many numbers go beside the grid */
  features: number;
  /** how many discrete actions the policy chooses from */
  actions: number;
  start(hello: HelloMsg): SeatEncoder;
}

export interface SeatEncoder {
  /** Writes this tick's observation into the seat's arrays. */
  encode(observation: Observation, out: EncoderOutput): void;
  /** The turn an action stands for, after the last observation encoded. */
  turn(action: number): TurnReply;
  /**
   * The action that comes closest to a turn, after the last observation encoded, or -1 if none
   * does. Needed to label actions: a teacher's, or a recorded match's for imitation.
   */
  action?(turn: TurnReply): number;
}

const BOTS = new Map<string, SimBot>();
const ENCODERS = new Map<string, SimEncoder>();
/** Encoders whose turns need no checking against the protocol's schema, since they can only build valid ones. */
const TRUSTED = new WeakSet<SimEncoder>();

/** Makes a bot available by name: as an opponent or a teacher in a `VectorBatch` (and Python's fast environments), or a `Game`'s opponent. */
export function registerBot(name: string, bot: SimBot): void {
  if (Object.hasOwn(HOUSE_BOTS, name)) throw new Error(`'${name}' is a house bot's name`);
  if (typeof bot?.start !== "function")
    throw new Error(`bot '${name}' has no start(hello) function`);
  BOTS.set(name, bot);
}

/** Makes an encoder available by name, for a `VectorBatch` (and Python's fast environments) to encode with. */
export function registerEncoder(name: string, encoder: SimEncoder): void {
  if (name === "basic") throw new Error("'basic' is the built-in encoder's name");
  validEncoder(encoder, name);
  ENCODERS.set(name, encoder);
}

/** The bots that can be named: the house bots, then the registered ones. */
export function botNames(): string[] {
  return [...Object.keys(HOUSE_BOTS), ...BOTS.keys()];
}

/** A bot by name (a house bot or a registered one), or as given, with the name replays record for it. */
export function resolveBot(bot: string | SimBot): { name: string; bot: SimBot } {
  if (typeof bot !== "string") {
    if (typeof bot?.start !== "function")
      throw new Error("a bot is a name or an object with start(hello)");
    return { name: bot.name ?? "bot", bot };
  }
  const house = Object.hasOwn(HOUSE_BOTS, bot)
    ? (HOUSE_BOTS as Record<string, SimBot>)[bot]
    : undefined;
  if (house) return { name: bot, bot: house };
  const registered = BOTS.get(bot);
  if (!registered) throw new Error(`unknown bot '${bot}' (${botNames().join(", ")})`);
  return { name: registered.name ?? bot, bot: registered };
}

/** What answers a bot's observations: each reply as the frame it sends. */
export function botReplies(bot: SimBot, hello: HelloMsg): (obs: Observation) => string | null {
  const decide = bot.start(hello);
  return (obs) => frameOf(decide(obs), obs.tick);
}

/** A reply as its JSON frame: null is no reply, and a turn without a tick gets this one. */
export function frameOf(turn: TurnReply | string | null, tick: number): string | null {
  if (turn === null || turn === undefined || typeof turn === "string") return turn ?? null;
  return JSON.stringify("tick" in turn ? turn : { tick, ...turn });
}

/** An encoder by name ("basic", which takes `size` and `grid`, or a registered one), or as given. */
export function resolveEncoder(
  encoder: string | SimEncoder | undefined,
  basic: { size: number; grid: "float32" | "uint8" },
): SimEncoder {
  if (encoder === undefined || encoder === "basic")
    return basicEncoder(basic.size, basic.grid === "uint8");
  if (typeof encoder !== "string") return validEncoder(encoder, "encoder");
  const found = ENCODERS.get(encoder);
  if (!found)
    throw new Error(
      `unknown encoder '${encoder}' (basic${[...ENCODERS.keys()].map((n) => `, ${n}`).join("")})`,
    );
  return found;
}

/** Whether an encoder's turns can skip the schema check. */
export function trusted(encoder: SimEncoder): boolean {
  return TRUSTED.has(encoder);
}

function validEncoder(e: SimEncoder, name: string): SimEncoder {
  const count = (n: unknown) => Number.isInteger(n) && (n as number) >= 0;
  if (!Array.isArray(e?.gridShape) || !e.gridShape.every(count))
    throw new Error(`${name}: gridShape is a list of sizes, e.g. [channels, height, width]`);
  if (!count(e.features))
    throw new Error(`${name}: features is how many numbers go beside the grid`);
  if (!count(e.actions) || e.actions < 1)
    throw new Error(`${name}: actions is how many actions the policy chooses from`);
  if (e.gridType !== undefined && e.gridType !== "float32" && e.gridType !== "uint8")
    throw new Error(`${name}: gridType is float32 or uint8`);
  if (typeof e.start !== "function")
    throw new Error(`${name}: start(hello) gives each seat's encoder`);
  return e;
}

/** How many values one seat's grid holds. */
export function gridLength(e: SimEncoder): number {
  return e.gridShape.reduce((a, b) => a * b, 1);
}

/** The built-in `Basic` encoder (the Python package's `Basic`), as a SimEncoder. */
export function basicEncoder(size = 21, codes = false): SimEncoder {
  const basic = new BasicEncoder(size, codes);
  const encoder: SimEncoder = {
    gridShape: [BASIC_CHANNELS.length, size, size],
    gridType: codes ? "uint8" : "float32",
    features: BASIC_FEATURES.length,
    actions: BASIC_ACTIONS,
    start(hello) {
      const map = { name: hello.map_name, tiles: hello.map };
      let last: Observation | null = null;
      let mask: Int8Array | null = null;
      return {
        encode(obs, out) {
          last = obs;
          mask = out.mask;
          basic.encode(obs, map, hello.rules as unknown as Rules, {
            ...out,
            at: { grid: 0, vec: 0, mask: 0 },
          });
        },
        turn: (action) => basicTurn(action, last!) as TurnReply,
        action(turn) {
          // An attack the mask refuses (on cooldown, out of reach) is one the engine would drop: what's left is the movement.
          const a = basicAction(turn);
          if (a >= 0 && mask![a]) return a;
          const still = basicAction({ ...turn, attack: undefined });
          return mask![still] ? still : -1;
        },
      };
    },
  };
  TRUSTED.add(encoder);
  return encoder;
}

const DIRS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];

/** The `Basic` action closest to a turn: its step or dash, and its attack by name (wherever it was aimed); -1 for an attack Basic doesn't have. */
export function basicAction(turn: TurnReply): number {
  const move = DIRS.indexOf(turn.move as string);
  const dash = DIRS.indexOf(turn.dash as string);
  const movement = move >= 0 ? 1 + move : dash >= 0 ? 9 + dash : 0;
  const name = (turn.attack as { name?: string } | undefined)?.name ?? null;
  const attack = BASIC_ATTACKS.indexOf(name as (typeof BASIC_ATTACKS)[number]);
  return attack < 0 ? -1 : movement * BASIC_ATTACKS.length + attack;
}
