// Match statistics, as sent in `end.stats` and served by GET /api/matches/<id>/stats.
// Mirrors MatchStats in the engine (packages/engine/src/stats.ts), which computes them.

import { z } from "zod";

const int = z.number().int();
const counts = (what: string) => z.record(z.string(), int).describe(what);

const Weapon = z
  .object({
    uses: int.describe("attacks fired: sent and accepted by the engine"),
    hits: int.describe("hits on an opponent"),
    damage: int.describe("hp those hits removed, the power buff included"),
  })
  .strict();

const Timing = z
  .object({
    replies: int.describe(
      "timed replies, timeouts included (a reply that never came counts at the deadline)",
    ),
    mean_ms: int,
    p50_ms: int.describe(
      "median reply; added up over several matches, the upper bound of its histogram bucket",
    ),
    p95_ms: int.describe(
      "95th percentile reply; added up over several matches, the upper bound of its histogram bucket",
    ),
    max_ms: int.describe("slowest reply"),
    near_limit: int.describe(
      "replies that took at least 80% of the tick limit: one slow moment from a timeout",
    ),
    tick_ms: int.describe("the per-tick limit the replies were timed against"),
    budget_ms: int.describe("the match's total response-time budget"),
    budget_ms_left: int.describe(
      "budget left at the end of the match (the lowest, added up over several)",
    ),
    histogram: z
      .array(int)
      .describe(
        "replies per bucket: upper bounds 10, 25, 50, 100, 200, 300, 400, 500, 600, 700, 800, 850, 900, 950, 1000 thousandths of tick_ms, then slower",
      ),
  })
  .strict()
  .describe(
    "how long the bot took to reply, as the server timed it: from sending the observation to the reply arriving, network included",
  );

const Fighter = z
  .object({
    occupancy: z
      .object({ width: int.positive(), height: int.positive(), counts: z.array(int.nonnegative()) })
      .strict()
      .optional()
      .describe(
        "Row-major occupancy: one sample at the start of each resolved tick while alive; absent in older statistics",
      ),
    id: int.describe("fighter id, as in hello.bot_id"),
    name: z.string(),
    version: z.string(),
    hp: int.describe("hp at the end of the match"),
    alive: z.boolean(),
    moves: int.describe("one-tile steps taken"),
    moves_blocked: int.describe(
      "accepted steps that didn't happen because another fighter was in the way",
    ),
    dashes: int,
    dash_tiles: int.describe("tiles covered by dashing"),
    weapons: z
      .record(z.string(), Weapon)
      .describe("by attack name; every attack in the rules is listed. Accuracy is hits / uses"),
    ricochets: z
      .object({
        bounces: int.describe("shots that bounced off a wall"),
        hits: int.describe("hits scored after a bounce (also counted in weapons)"),
        damage: int,
      })
      .strict(),
    pickups: counts("pickups taken, by kind; every kind in the rules is listed"),
    healed: int.describe("hp restored by health pickups"),
    damage_dealt: int.describe("hp removed from opponents"),
    dealt_by_source: counts('damage_dealt by source: attack names, "wall_slam", "collision"'),
    damage_taken: int.describe("hp lost"),
    taken_by_source: counts(
      'damage_taken by source: attack names, "wall_slam", "collision", "zone"',
    ),
    wall_slams: int.describe("opponents this fighter's repulsor slammed into a wall"),
    knocked_back: int.describe("times this fighter was shoved"),
    stunned: int.describe("times this fighter was stunned"),
    zone_ticks: int.describe("ticks ended outside the safe zone"),
    rejected: counts("parts of turns the engine refused, by reason"),
    refused_turns: int.describe("turns with at least one refused part"),
    refused_turns_by_reason: counts(
      "turns with a refused part, by reason; a turn counts once per reason",
    ),
    server_idles: counts(
      "ticks the server played as idle for this fighter, by reason (timeout, malformed_json, disconnected…)",
    ),
    timing: Timing.nullable().describe(
      "reply times; null when nothing was timed (the simulator doesn't time replies)",
    ),
    disconnects: int.describe(
      "contiguous runs of recorded disconnected idle turns for this fighter, not socket-close events",
    ),
    disqualified: z
      .boolean()
      .describe("the match ended because this fighter failed too many ticks in a row"),
  })
  .strict();

export const MatchStats = z
  .object({
    stats_version: int.describe("bumped whenever a field changes meaning"),
    map: z.string(),
    seed: int,
    ticks: int.describe("ticks resolved"),
    winner: int.nullable().describe("fighter id of the winner, or null for a draw"),
    reason: z.string().nullable().describe("how the match ended"),
    fighters: z.array(Fighter),
  })
  .strict()
  .describe("what each fighter did over one match");

export type MatchStats = z.infer<typeof MatchStats>;
