// Wire protocol (see PROTOCOL_VERSION). Every WebSocket text frame carries exactly one JSON object.
// Messages from bots are validated strictly: wrong types and unknown fields are rejected.

import { z } from "zod";
import { MatchStats } from "./stats.ts";

/** Bumped whenever a bot-facing message changes shape. 0.2 introduced the `turn` message; 0.3 made
 *  `queue` just a version and removed availability and challenges; 0.4 added `shout`;
 *  0.5 added the ladder's `server_draining` notice; 0.6 added optional ladder IDs; 0.7 added `quota_exceeded`'s quota fields. */
export const PROTOCOL_VERSION = "0.7";

export { ObservationMsg, SERVER_REJECT_REASONS, observationSchema } from "./observation.ts";
export { MatchStats };

const Dir = z.enum(["N", "NE", "E", "SE", "S", "SW", "W", "NW"]);
const Tile = z.tuple([z.number().int(), z.number().int()]);

// ------------------------------------------------------------ bot → server

/** Asks for the next match, played with this version; send it again after each `end`. */
export const QueueMsg = z
  .object({
    type: z.literal("queue"),
    version: z.string().min(1).max(32),
    ladder_id: z
      .string()
      .regex(/^[a-z0-9][a-z0-9-]{1,63}$/)
      .optional()
      .describe(
        "Ladder to enter; omitted means public. Event ladders require active account enrollment.",
      ),
  })
  .strict();

export const ReadyMsg = z.object({ type: z.literal("ready") }).strict();
export const LeaveMsg = z.object({ type: z.literal("leave") }).strict();

/**
 * A turn: what a bot does this tick. Messages carry no `type` (it may be given as "turn") and must
 * echo the observation's tick. The movement phase is `move` (a step) or `dash`, or neither, and the
 * attack phase follows it, firing from where the fighter ends up. A `shout` goes with any of them.
 * An empty turn is idle.
 */
export const TurnMsg = z
  .object({
    type: z.literal("turn").optional(),
    tick: z.number().int().nonnegative(),
    move: Dir.optional().describe("step one tile in this direction"),
    dash: Dir.optional().describe(
      "dash up to the dash distance in this direction; not together with `move`",
    ),
    attack: z
      .object({
        name: z.string().max(32).describe("a key of hello.rules.attacks"),
        target: Tile.optional().describe(
          "the tile to aim at; the repulsor has no aim and ignores it",
        ),
      })
      .strict()
      .optional()
      .describe("fires after the movement, from the tile you end on"),
    // The engine enforces the real limit (hello.rules.shout.max_length characters); this only
    // caps what the server will read.
    shout: z
      .string()
      .max(200)
      .optional()
      .describe(
        "say something to everyone: your opponent sees it as a `shout` event and it shows in the replay. At most hello.rules.shout.max_length (40) characters, once per hello.rules.shout.cooldown ticks, in any state; profanity is masked with *",
      ),
  })
  .strict()
  .refine((m) => m.move === undefined || m.dash === undefined, {
    message: "give `move` or `dash`, not both",
    path: ["dash"],
  });

export type QueueMsg = z.infer<typeof QueueMsg>;
export type TurnMsg = z.infer<typeof TurnMsg>;

export type BotMessage =
  | { kind: "queue"; msg: QueueMsg }
  | { kind: "ready" }
  | { kind: "leave" }
  | { kind: "turn"; msg: TurnMsg };

const BY_TYPE: Record<string, z.ZodTypeAny> = {
  queue: QueueMsg,
  ready: ReadyMsg,
  leave: LeaveMsg,
  turn: TurnMsg,
};

export type ParseResult =
  | { ok: true; value: BotMessage }
  | { ok: false; code: "malformed_json" | "schema"; message: string };

export function parseBotMessage(text: string): ParseResult {
  let obj: unknown;
  try {
    obj = JSON.parse(text);
  } catch {
    return { ok: false, code: "malformed_json", message: "frame is not valid JSON" };
  }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) {
    return { ok: false, code: "schema", message: "frame must be a JSON object" };
  }
  const raw = (obj as { type?: unknown }).type;
  const type = raw === undefined ? "turn" : raw;
  const schema =
    typeof type === "string" && Object.hasOwn(BY_TYPE, type) ? BY_TYPE[type] : undefined;
  if (!schema)
    return { ok: false, code: "schema", message: `unknown message type ${JSON.stringify(raw)}` };
  const r = schema.safeParse(obj);
  if (!r.success) {
    const issue = r.error.issues[0]!;
    return {
      ok: false,
      code: "schema",
      message: `${issue.path.join(".") || "(root)"}: ${issue.message}`,
    };
  }
  if (type === "ready" || type === "leave") return { ok: true, value: { kind: type } };
  return { ok: true, value: { kind: type, msg: r.data } as BotMessage };
}

// ------------------------------------------------------------ server → bot
// These describe what the server sends. Bots must ignore unknown fields, so these
// schemas are documentation and test fixtures rather than something bots enforce.

export const QueuedMsg = z.object({
  type: z.literal("queued"),
  version: z.string(),
  estimated_wait_s: z.number(),
  ladder_id: z.string().optional(),
});

/** Ladder only: matchmaking has stopped; keep answering active matches until closure. */
export const ServerDrainingMsg = z.object({
  type: z.literal("server_draining"),
  drain_deadline: z
    .string()
    .datetime()
    .describe(
      "UTC deadline for waiting on active matches; the server may close earlier. This is not an estimate of when connections will be accepted again.",
    ),
});

export const HelloMsg = z.object({
  type: z.literal("hello"),
  protocol_version: z.literal(PROTOCOL_VERSION),
  match_id: z.string(),
  bot_id: z.number().int(),
  opponent: z.object({ bot_id: z.number().int(), name: z.string() }),
  rules: z.record(z.string(), z.unknown()),
  map: z.array(z.string()),
  map_name: z.string(),
  /** every pickup pad on the map; pad ids match observation.pickups */
  pickups: z.array(
    z.object({
      id: z.number().int(),
      pos: z.tuple([z.number().int(), z.number().int()]),
      kind: z.string(),
    }),
  ),
  seed_public: z.number().int(),
  deadlines: z.object({ startup_ms: z.number(), tick_ms: z.number(), match_budget_ms: z.number() }),
});

export const EndMsg = z.object({
  type: z.literal("end"),
  ladder_id: z.string().optional(),
  match_id: z.string(),
  result: z.enum(["win", "loss", "draw"]),
  reason: z.string(),
  final_tick: z.number().int(),
  opponent_version: z.string(),
  replay_url: z.string().nullable(),
  rating_change: z.number().nullable(),
  voided: z.boolean().optional(),
  /** ladder only: link that opens the match in the viewer */
  watch_url: z.string().optional(),
  /** what each fighter did over the match; absent for a voided match */
  stats: MatchStats.optional(),
});

export const ErrorMsg = z.object({
  type: z.literal("error"),
  code: z.string(),
  message: z.string(),
  /** quota_exceeded only: the quota holding the bot back, by its name in GET /api `quotas` */
  quota: z.string().optional(),
  /** quota_exceeded only: the quota's current value */
  limit: z.number().int().optional(),
  /** quota_exceeded only: how much of it is used (matches in the rolling window, or running) */
  used: z.number().int().optional(),
  /** quota_exceeded only: seconds until the rolling window frees a place; null when that waits on a running match */
  retry_after_s: z.number().int().nullable().optional(),
});

export type HelloMsg = z.infer<typeof HelloMsg>;
export type EndMsg = z.infer<typeof EndMsg>;
export type QueuedMsg = z.infer<typeof QueuedMsg>;
export type ServerDrainingMsg = z.infer<typeof ServerDrainingMsg>;
export type ErrorMsg = z.infer<typeof ErrorMsg>;
